using LaboratoryDesktopApp.DemoData;
using LaboratoryDesktopApp.Models;
using LaboratoryDesktopApp.Theme;

namespace LaboratoryDesktopApp.Controls;

public class WorkflowControl : UserControl
{
    private readonly string _page;
    private readonly DataGridView grid = new();
    private readonly Label hint = new();
    public WorkflowControl(string page) { _page=page; Dock=DockStyle.Fill; BackColor=AppTheme.Background; Padding=new Padding(24); Build(); RefreshData(); }
    private void Build() {
        var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4}; root.RowStyles.Add(new RowStyle(SizeType.Absolute,54));root.RowStyles.Add(new RowStyle(SizeType.Absolute,48));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,34));
        var title=new Label{Text=_page,Font=AppTheme.PageTitle,ForeColor=AppTheme.MainText,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft};root.Controls.Add(title,0,0);
        var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.LeftToRight,WrapContents=false};
        AddButton(actions,"Refresh",RefreshData); if(_page=="Patients") AddButton(actions,"Register patient",AddPatient); if(_page=="Test Orders") AddButton(actions,"Create test order",AddOrder); if(_page=="Samples") AddButton(actions,"Register / update sample",UpdateSample); if(_page=="Results") AddButton(actions,"Enter results",EnterResults); if(_page=="Reports") AddButton(actions,"Export summary (CSV)",ExportSummary); if(_page=="Dashboard") AddButton(actions,"Refresh overview",RefreshData);
        root.Controls.Add(actions,0,1);
        grid.Dock=DockStyle.Fill;grid.BackgroundColor=Color.White;grid.BorderStyle=BorderStyle.None;grid.AllowUserToAddRows=false;grid.AllowUserToDeleteRows=false;grid.ReadOnly=true;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.MultiSelect=false;grid.RowHeadersVisible=false;grid.EnableHeadersVisualStyles=false;grid.ColumnHeadersDefaultCellStyle.BackColor=AppTheme.PrimaryLight;grid.ColumnHeadersDefaultCellStyle.ForeColor=AppTheme.MainText;grid.ColumnHeadersDefaultCellStyle.Font=AppTheme.Label;grid.DefaultCellStyle.Font=AppTheme.Body;grid.DefaultCellStyle.SelectionBackColor=AppTheme.PrimaryLight;grid.DefaultCellStyle.SelectionForeColor=AppTheme.MainText;grid.RowTemplate.Height=36;root.Controls.Add(grid,0,2);
        hint.Text="Demo mode: all changes are temporary and disappear when the app closes.";hint.ForeColor=AppTheme.SecondaryText;hint.Dock=DockStyle.Fill;hint.TextAlign=ContentAlignment.MiddleLeft;root.Controls.Add(hint,0,3);Controls.Add(root);
    }
    private static void AddButton(Control parent,string text,Action action){var b=new Button{Text=text,AutoSize=true,Height=36,Padding=new Padding(12,0,12,0),FlatStyle=FlatStyle.Flat,BackColor=AppTheme.Primary,ForeColor=Color.White,Font=AppTheme.Label,Cursor=Cursors.Hand,Margin=new Padding(0,4,10,4)};b.FlatAppearance.BorderSize=0;b.Click+=(_,_)=>action();parent.Controls.Add(b);}
    private void RefreshData(){grid.DataSource=null; switch(_page){
      case "Dashboard": grid.DataSource=new[]{new{Metric="Registered patients",Count=DemoDataProvider.Patients.Count},new{Metric="Test orders",Count=DemoDataProvider.Orders.Count},new{Metric="Samples registered",Count=DemoDataProvider.Samples.Count},new{Metric="Results entered",Count=DemoDataProvider.Results.Count},new{Metric="Available tests",Count=DemoDataProvider.Tests.Count}};hint.Text="Workflow: Register patient → Create order → Track sample → Enter results → Review report.";break;
      case "Patients": grid.DataSource=DemoDataProvider.Patients.Select(x=>new{Code=x.PatientCode,Name=x.FullName,Phone=x.Phone,Gender=x.Gender,DateOfBirth=x.DateOfBirth.ToString("yyyy-MM-dd"),Notes=x.Notes}).ToList();break;
      case "Test Orders": grid.DataSource=DemoDataProvider.Orders.Select(x=>new{Order=x.OrderCode,Patient=DemoDataProvider.PatientFor(x.PatientId)?.FullName??"Unknown",Tests=string.Join(", ",x.TestCodes),Created=x.CreatedAt.ToString("yyyy-MM-dd HH:mm"),x.Status}).ToList();break;
      case "Samples": grid.DataSource=DemoDataProvider.Samples.Select(x=>new{Sample=x.SampleCode,Order=DemoDataProvider.OrderFor(x.OrderId)?.OrderCode??"Unknown",Patient=DemoDataProvider.PatientFor(DemoDataProvider.OrderFor(x.OrderId)?.PatientId??-1)?.FullName??"Unknown",x.Barcode,x.SampleType,Collected=x.CollectedAt.ToString("yyyy-MM-dd HH:mm"),x.Status}).ToList();break;
      case "Results": grid.DataSource=DemoDataProvider.Results.Select(x=>new{Order=DemoDataProvider.OrderFor(x.OrderId)?.OrderCode??"Unknown",Patient=DemoDataProvider.PatientFor(DemoDataProvider.OrderFor(x.OrderId)?.PatientId??-1)?.FullName??"Unknown",x.TestCode,x.Parameter,x.Value,x.Unit,x.ReferenceRange,x.Status,Updated=x.UpdatedAt.ToString("yyyy-MM-dd HH:mm")}).ToList();break;
      case "Reports": grid.DataSource=DemoDataProvider.Orders.Select(o=>new{Order=o.OrderCode,Patient=DemoDataProvider.PatientFor(o.PatientId)?.FullName??"Unknown",Tests=string.Join(", ",o.TestCodes),o.Status,ResultCount=DemoDataProvider.Results.Count(r=>r.OrderId==o.Id)}).ToList();hint.Text="Illustrative operational summary only; reference ranges and results are not medical advice.";break;
      default: grid.DataSource=DemoDataProvider.Tests.Select(t=>new{t.Code,t.Name,t.Category,t.SampleType,t.Price,TurnaroundHours=t.TurnaroundHours,Parameters=t.Parameters.Count}).ToList();break;
    }}
    private void AddPatient(){using var f=new Form{Text="Register patient",Size=new Size(480,430),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false};var table=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(18),ColumnCount=2,RowCount=6};table.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,130));table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));for(int i=0;i<6;i++)table.RowStyles.Add(new RowStyle(SizeType.Absolute,48));
      var name=Field(table,"Full name",0);var phone=Field(table,"Phone",1);var gender=new ComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList};gender.Items.AddRange(new object[]{"Female","Male","Other / not specified"});gender.SelectedIndex=2;table.Controls.Add(new Label{Text="Gender",TextAlign=ContentAlignment.MiddleLeft},0,2);table.Controls.Add(gender,1,2);var dob=new DateTimePicker{Dock=DockStyle.Fill,Format=DateTimePickerFormat.Short,MaxDate=DateTime.Today};table.Controls.Add(new Label{Text="Date of birth",TextAlign=ContentAlignment.MiddleLeft},0,3);table.Controls.Add(dob,1,3);var notes=Field(table,"Notes",4);var save=new Button{Text="Save patient",Dock=DockStyle.Fill,BackColor=AppTheme.Primary,ForeColor=Color.White};table.Controls.Add(save,1,5);save.Click+=(_,_)=>{if(string.IsNullOrWhiteSpace(name.Text)){MessageBox.Show("Enter the patient's full name.");return;}DemoDataProvider.Patients.Add(new Patient{Id=DemoDataProvider.NextPatientId++,FullName=name.Text.Trim(),Phone=phone.Text.Trim(),Gender=gender.Text,DateOfBirth=dob.Value.Date,Notes=notes.Text.Trim()});f.DialogResult=DialogResult.OK;f.Close();};f.Controls.Add(table);if(f.ShowDialog(FindForm())==DialogResult.OK)RefreshData();}
    private static TextBox Field(TableLayoutPanel t,string label,int row){t.Controls.Add(new Label{Text=label,TextAlign=ContentAlignment.MiddleLeft},0,row);var box=new TextBox{Dock=DockStyle.Fill};t.Controls.Add(box,1,row);return box;}
    private void AddOrder(){if(DemoDataProvider.Patients.Count==0){MessageBox.Show("Register a patient first.");return;}var active=DemoDataProvider.Tests.ToList();using var f=new Form{Text="Create test order",Size=new Size(560,520),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog};var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(18),RowCount=5,ColumnCount=1};root.RowStyles.Add(new RowStyle(SizeType.Absolute,28));root.RowStyles.Add(new RowStyle(SizeType.Absolute,42));root.RowStyles.Add(new RowStyle(SizeType.Absolute,38));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,48));var patient=new ComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList,DataSource=DemoDataProvider.Patients.ToList(),DisplayMember="FullName"};root.Controls.Add(new Label{Text="Select patient",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft},0,0);root.Controls.Add(patient,0,1);var label=new Label{Text="Select one or more tests",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft};root.Controls.Add(label,0,2);var tests=new CheckedListBox{Dock=DockStyle.Fill,CheckOnClick=true};foreach(var t in active)tests.Items.Add($"{t.Code} — {t.Name}",true);root.Controls.Add(tests,0,3);var save=new Button{Text="Create order",Dock=DockStyle.Fill,BackColor=AppTheme.Primary,ForeColor=Color.White};root.Controls.Add(save,0,4);save.Click+=(_,_)=>{var codes=tests.CheckedItems.Cast<string>().Select(s=>s.Split(' ')[0]).Distinct().ToList();if(codes.Count==0){MessageBox.Show("Select at least one test.");return;}var order=new TestOrder{Id=DemoDataProvider.NextOrderId++,PatientId=((Patient)patient.SelectedItem!).Id,TestCodes=codes};DemoDataProvider.Orders.Add(order);f.DialogResult=DialogResult.OK;f.Close();};f.Controls.Add(root);if(f.ShowDialog(FindForm())==DialogResult.OK)RefreshData();}
    private void UpdateSample(){if(DemoDataProvider.Orders.Count==0){MessageBox.Show("Create a test order first.");return;}using var f=new Form{Text="Register sample",Size=new Size(460,320),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog};var t=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(18),ColumnCount=2,RowCount=4};t.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,120));t.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));for(int i=0;i<4;i++)t.RowStyles.Add(new RowStyle(SizeType.Absolute,50));var order=new ComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList,DataSource=DemoDataProvider.Orders.ToList(),DisplayMember="OrderCode"};var barcode=new TextBox{Dock=DockStyle.Fill,Text=$"BC-{DateTime.Now:MMddHHmmss}"};var type=new ComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList};type.Items.AddRange(new object[]{"Whole blood","Serum","Plasma","Urine","Swab","Other"});type.SelectedIndex=0;var status=new ComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList};status.Items.AddRange(new object[]{"Collected","In processing","Received","Rejected"});status.SelectedIndex=0;AddRow(t,"Order",order,0);AddRow(t,"Barcode",barcode,1);AddRow(t,"Sample type",type,2);AddRow(t,"Status",status,3);var save=new Button{Text="Save sample",Dock=DockStyle.Bottom,Height=40,BackColor=AppTheme.Primary,ForeColor=Color.White};save.Click+=(_,_)=>{var o=(TestOrder)order.SelectedItem!;var s=DemoDataProvider.Samples.FirstOrDefault(x=>x.OrderId==o.Id);if(s==null){s=new Sample{Id=DemoDataProvider.NextSampleId++,OrderId=o.Id};DemoDataProvider.Samples.Add(s);}s.Barcode=barcode.Text.Trim();s.SampleType=type.Text;s.Status=status.Text;s.CollectedAt=DateTime.Now;o.Status=status.Text=="Rejected"?"Sample rejected":status.Text=="Collected"?"Sample collected":"Sample: "+status.Text;f.DialogResult=DialogResult.OK;f.Close();};f.Controls.Add(t);f.Controls.Add(save);if(f.ShowDialog(FindForm())==DialogResult.OK)RefreshData();}
    private static void AddRow(TableLayoutPanel t,string name,Control c,int row){t.Controls.Add(new Label{Text=name,TextAlign=ContentAlignment.MiddleLeft},0,row);t.Controls.Add(c,1,row);}
    private void EnterResults(){if(DemoDataProvider.Orders.Count==0){MessageBox.Show("Create an order first.");return;}using var f=new Form{Text="Enter test results",Size=new Size(650,520),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog};var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),ColumnCount=1,RowCount=5};root.RowStyles.Add(new RowStyle(SizeType.Absolute,40));root.RowStyles.Add(new RowStyle(SizeType.Absolute,40));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,38));root.RowStyles.Add(new RowStyle(SizeType.Absolute,44));var order=new ComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList,DataSource=DemoDataProvider.Orders.ToList(),DisplayMember="OrderCode"};root.Controls.Add(order,0,0);var test=new ComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList};root.Controls.Add(test,0,1);order.SelectedIndexChanged+=(_,_)=>{test.Items.Clear();if(order.SelectedItem is TestOrder o)foreach(var code in o.TestCodes){var lab=DemoDataProvider.Tests.FirstOrDefault(x=>x.Code==code);if(lab!=null)test.Items.Add(lab);}if(test.Items.Count>0)test.SelectedIndex=0;};if(order.Items.Count>0){order.SelectedIndex=0;}var values=new DataGridView{Dock=DockStyle.Fill,AllowUserToAddRows=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};values.Columns.Add("Parameter","Parameter");values.Columns.Add("Value","Result value");values.Columns.Add("Unit","Unit");values.Columns.Add("Reference","Demo reference range");root.Controls.Add(values,0,2);test.SelectedIndexChanged+=(_,_)=>{values.Rows.Clear();if(test.SelectedItem is LabTest lt){foreach(var par in lt.Parameters.OrderBy(x=>x.DisplayOrder))values.Rows.Add(par.Name,"",par.Unit,"Demo only");if(values.Rows.Count==0)values.Rows.Add(lt.Name,"","","Demo only");}};var status=new ComboBox{Dock=DockStyle.Fill,DropDownStyle=ComboBoxStyle.DropDownList};status.Items.AddRange(new object[]{"Draft","Reviewed","Approved"});status.SelectedIndex=0;root.Controls.Add(status,0,3);var save=new Button{Text="Save results",Dock=DockStyle.Fill,BackColor=AppTheme.Primary,ForeColor=Color.White};root.Controls.Add(save,0,4);save.Click+=(_,_)=>{if(order.SelectedItem is not TestOrder o||test.SelectedItem is not LabTest lt){MessageBox.Show("Select an order and test.");return;}int saved=0;foreach(DataGridViewRow row in values.Rows){if(row.IsNewRow)continue;var param=Convert.ToString(row.Cells[0].Value)??"";var value=Convert.ToString(row.Cells[1].Value)??"";if(string.IsNullOrWhiteSpace(param)||string.IsNullOrWhiteSpace(value))continue;var existing=DemoDataProvider.Results.FirstOrDefault(x=>x.OrderId==o.Id&&x.TestCode==lt.Code&&x.Parameter==param);if(existing==null){existing=new TestResult{Id=DemoDataProvider.NextResultId++,OrderId=o.Id,TestCode=lt.Code,Parameter=param};DemoDataProvider.Results.Add(existing);}existing.Value=value;existing.Unit=Convert.ToString(row.Cells[2].Value)??"";existing.ReferenceRange=Convert.ToString(row.Cells[3].Value)??"Demo only";existing.Status=status.Text;existing.UpdatedAt=DateTime.Now;saved++;}if(saved==0){MessageBox.Show("Enter at least one result value.");return;}if(status.Text=="Approved")o.Status="Results approved";else if(status.Text=="Reviewed")o.Status="Results under review";else o.Status="Results in progress";f.DialogResult=DialogResult.OK;f.Close();};f.Controls.Add(root);if(f.ShowDialog(FindForm())==DialogResult.OK)RefreshData();}
    private void ExportSummary(){using var dialog=new SaveFileDialog{Filter="CSV file (*.csv)|*.csv",FileName="lab-report-summary.csv"};if(dialog.ShowDialog()!=DialogResult.OK)return;var lines=new List<string>{"Order,Patient,Tests,Status,ResultCount"};foreach(var o in DemoDataProvider.Orders){string patient=DemoDataProvider.PatientFor(o.PatientId)?.FullName??"Unknown";string tests=string.Join(";",o.TestCodes);int count=DemoDataProvider.Results.Count(r=>r.OrderId==o.Id);lines.Add($"\"{o.OrderCode}\",\"{patient.Replace("\"","\"\"")}\",\"{tests}\",\"{o.Status}\",{count}");}File.WriteAllLines(dialog.FileName,lines);MessageBox.Show("Demo CSV summary exported.");}
}
